func (q *Queries) ListContentSections(ctx context.Context, arg ListContentSectionsParams) ([]TechnicalPlanContentSection, error) {
	rows, err := q.db.Query(ctx, listContentSections, arg.ProjectID, arg.TenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TechnicalPlanContentSection{}
	for rows.Next() {
		var i TechnicalPlanContentSection
		if err := rows.Scan(
			&i.NodeID,
			&i.ProjectID,
			&i.TenantID,
			&i.Status,
			&i.Error,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

