//
// 用递归 CTE 生成 path（如 "0001.0003.0002"），按 path 排序即得深度优先序。
func (q *Queries) ListOutlineNodes(ctx context.Context, arg ListOutlineNodesParams) ([]TechnicalPlanOutlineNode, error) {
	rows, err := q.db.Query(ctx, listOutlineNodes, arg.ProjectID, arg.TenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TechnicalPlanOutlineNode{}
	for rows.Next() {
		var i TechnicalPlanOutlineNode
		if err := rows.Scan(
			&i.NodeID,
			&i.ProjectID,
			&i.TenantID,
			&i.ParentNodeID,
			&i.SortOrder,
			&i.Level,
			&i.Title,
			&i.Description,
			&i.ContentMode,
			&i.ContentModeNote,
			&i.RuleBasis,
			&i.SourceRequirementID,
			&i.SourceRequirementTitle,
			&i.KnowledgeItemIds,
			&i.Content,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ExternalID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

